1	import java.awt.*;
2	import javax.swing.*;
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	import java.awt.event.ActionListener;
6	import javax.swing.border.LineBorder;
7	
8	/**
9	 * A graphical view of the simulation grid.
10	 * The view displays a colored rectangle for each location 
11	 * representing its contents. It uses a default background color.
12	 * Colors for each type of species can be defined using the
13	 * setColor method.
14	 *
15	 * @version 2022.02.28
16	 */
17	public class SimulatorView extends JFrame
18	{
19	    // Color used for empty locations.
20	    private static final Color EMPTY_COLOR = Color.white;
21	    // Color used for objects that have no defined color.
22	    private static final Color UNKNOWN_COLOR = Color.gray;
23	    // Prefix preceding the step count.
24	    private final String STEP_PREFIX = "Step: ";
25	    // Prefix preceding the current time display.
26	    private final String TIME_PREFIX = "Time: ";
27	    // Prefix preceding the current temperature display.
28	    private final String TEMPERATURE_PREFIX = "Temperature: ";
29	    // Prefix preceding the current season display.
30	    private final String SEASON_PREFIX = "Season: ";
31	    // JLabels for all the previously mentioned information displays.
32	    private JLabel stepLabel, infoLabel, timeLabel, temperatureLabel, seasonLabel;
33	    // Container to show population data.
34	    private JPanel population;
35	    // The grid view showing the state of the field at each step.
36	    private FieldView fieldView;
37	
38	    // A map for storing colors for participants in the simulation
39	    private Map<String, Color> colors;
40	    // A statistics object computing and storing simulation information
41	    private FieldStats stats;
42	    // The GUIHandler governing the simulation's GUI.
43	    private GUIHandler handler;
44	
45	    /**
46	     * Constructor has two roles:
47	     *      1) Initializing the fields.
48	     *      2) Building the view.
49	     *
50	     * @param height (int) The simulation's height.
51	     * @param width (int) The simulation's width.
52	     */
53	    public SimulatorView(int height, int width, GUIHandler handler)
54	    {
55	        // INITIALIZES FIELDS
56	        this.handler = handler;
57	        stats = new FieldStats();
58	        colors = new LinkedHashMap<>();
59	
60	        // Various information labels initialization.
61	        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
62	        infoLabel = new JLabel("  ", JLabel.CENTER);
63	        timeLabel = new JLabel(TIME_PREFIX, JLabel.CENTER);
64	        temperatureLabel = new JLabel(TEMPERATURE_PREFIX, JLabel.CENTER);
65	        seasonLabel = new JLabel(SEASON_PREFIX, JLabel.CENTER);
66	
67	        // Population display initialization.
68	        population = new JPanel();
69	        GridLayout gridLayout = new GridLayout(5,5);
70	        population.setLayout(gridLayout);
71	
72	        fieldView = new FieldView(height, width);
73	
74	        // BUILDS THE VIEW
75	        JFrame frame = new JFrame("Ultimate Simulator 3000");
76	        frame.setMinimumSize(new Dimension(800, 600));
77	
78	        // Information display on habitat conditions and step counter.
79	        FlowLayout simInfo = new FlowLayout();
80	        simInfo.setHgap(50);
81	
82	        JPanel infoPane = new JPanel(simInfo);
83	        infoPane.add(infoLabel, BorderLayout.CENTER);
84	        infoPane.add(stepLabel, BorderLayout.CENTER);
85	        infoPane.add(timeLabel, BorderLayout.CENTER);
86	        infoPane.add(seasonLabel, BorderLayout.CENTER);
87	        infoPane.add(temperatureLabel, BorderLayout.CENTER);
88	
89	        // Various buttons for user to interact with the simulation.
90	        JButton launchLongSimButton = new JButton("Launch long simulation");
91	        ActionListener launchLongSim = e -> {
92	            handler.launchLongSimulation();
93	        };
94	        launchLongSimButton.addActionListener(launchLongSim);
95	        
96	        JButton launchHundredStepsButton = new JButton("Run 100 steps");
97	        ActionListener launchHundredSteps = e -> {
98	            handler.runHundredSteps();
99	        };
100	        launchHundredStepsButton.addActionListener(launchHundredSteps);
101	        
102	        JButton launchOneStepButton  = new JButton("Run 1 step");
103	        ActionListener launchOneStep = e -> {
104	            handler.runOneStep();
105	        };
106	        launchOneStepButton.addActionListener(launchOneStep);
107	        
108	        JButton goBackMenuButton  = new JButton("Run a new simulation");
109	        ActionListener goBackMenu = e -> {
110	            setVisible(false);
111	            handler.switchToMenuView();
112	        };
113	        goBackMenuButton.addActionListener(goBackMenu);
114	
115	        // Bringing the UI together.
116	        JPanel buttons = new JPanel(new FlowLayout());
117	        buttons.add(launchLongSimButton);
118	        buttons.add(launchHundredStepsButton);
119	        buttons.add(launchOneStepButton);
120	        buttons.add(goBackMenuButton);
121	        
122	        Box bottomComponents = Box.createVerticalBox();
123	        bottomComponents.add(population);
124	        bottomComponents.add(buttons);
125	        
126	        JPanel centeredFieldView = new JPanel(new BorderLayout());
127	        centeredFieldView.add(fieldView, BorderLayout.CENTER);
128	        add(infoPane, BorderLayout.NORTH);
129	        add(fieldView, BorderLayout.CENTER);
130	        add(bottomComponents, BorderLayout.SOUTH);
131	
132	        pack();
133	        setVisible(true);
134	    }
135	
136	    /**
137	     * Define a color to be used for a given class of specie.
138	     *
139	     * @param speciesName (String) The specie's name.
140	     * @param color (Color) The color to be used for the given class.
141	     */
142	    public void setColor(String speciesName, Color color)
143	    {
144	        colors.put(speciesName, color);
145	    }
146	
147	    /**
148	     * Display a short information label at the top of the window.
149	     */
150	    public void setInfoText(String text)
151	    {
152	        infoLabel.setText(text);
153	    }
154	
155	    /**
156	     * @return (Color) The color to be used for a given class of specie.
157	     */
158	    private Color getColor(String speciesName)
159	    {
160	        Color col = colors.get(speciesName);
161	        if(col == null) {
162	            // no color defined for this class
163	            return UNKNOWN_COLOR;
164	        }
165	        else {
166	            return col;
167	        }
168	    }
169	
170	    /**
171	     * Show the current status of the field.
172	     *
173	     * @param step (int) Which iteration step it is.
174	     * @param time (String) The current time in the simulation
175	     * @param season (String) The current season in the simulation
176	     * @param temperature (int) The current temperature in the simulation
177	     * @param field (Field) The field whose status is to be displayed.
178	     */
179	    public void showStatus(int step, String time, String season, int temperature, Field field)
180	    {
181	        if(!isVisible()) {
182	            setVisible(true);
183	        }
184	
185	        stepLabel.setText(STEP_PREFIX + step);
186	        timeLabel.setText(TIME_PREFIX + time);
187	        seasonLabel.setText(SEASON_PREFIX + season);
188	        temperatureLabel.setText(TEMPERATURE_PREFIX + temperature + " C");
189	        stats.reset();
190	
191	        fieldView.preparePaint();
192	
193	        for(int row = 0; row < field.getDepth(); row++)
194	        {
195	            for(int col = 0; col < field.getWidth(); col++)
196	            {
197	                Object specie = field.getObjectAt(row, col);
198	                if(specie != null) {
199	                    Species speciesObjects = (Species) specie;
200	                    stats.incrementCount(speciesObjects.getName());
201	                    fieldView.drawMark(col, row, getColor(speciesObjects.getName()));
202	                }
203	                else {
204	                    fieldView.drawMark(col, row, EMPTY_COLOR);
205	                }
206	            }
207	        }
208	        stats.countFinished();
209	        
210	        fieldView.repaint();
211	        generatePopulationComponent(field);
212	    }
213	    
214	    /**
215	     * Generates a population component with the color, count, and name of each species present in the simulation.
